              "summary": "- 말보로와 아이코스 등으로 유명한 글로벌 담배 시장점유율 1위 업체- 3분기 매출액 및 조정 DEPS는 시장 컨센서스 부합- 다만, 최근 SFP 매출 성장세 둔화되고 있기 때문에, 향후 성장률 변화 확인 필요",
